                new double[] { p[0], p[1], p[2] }, 0);
        Collection<LinearConstraint> constraints = new ArrayList<LinearConstraint>();
        for (int i = 0; i < 3; i++) {
            constraints.add(new LinearConstraint(
                    new double[] { p[3 + 3 * i], p[4 + 3 * i], p[5 + 3 * i] },
                    Relationship.LEQ, p[12 + i]));
        }

